        rev = [[] for _ in range(n)]
        max_w = 0

        for a, b, w in edges:
            rev[b].append((a, w))
            max_w = max(max_w, w)

        def can(limit: int) -> bool:
            seen = [False] * n
            seen[0] = True
            stack = [0]
            count = 1

